h1 {
  color: navy;
  font-size: 2rem;
}

body { color: #333; }
/* children inherit color, font */
/* margin and border do not inherit */

color: red;
color: #1e90ff;
color: rgb(30 144 255 / 50%);
color: hsl(210 100% 56%);
color: oklch(0.7 0.15 250);

div {
  width: 200px;
  padding: 10px;
  border: 2px solid;
  margin: 20px;
}

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  font: 16px/1.5 system-ui, sans-serif;
  font-weight: 600;
  text-align: center;
  letter-spacing: .02em;
}

div {
  background: url(a.png) center/cover no-repeat, #eee;
  border-radius: 12px;
  box-shadow: 0 4px 12px #0003;
}

display: block | inline | inline-block | none | flex | grid;
visibility: hidden;
opacity: .5;

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

flex: 1 1 0;
/* grow shrink basis */
flex-wrap: wrap;
order: 2;
align-self: flex-end;

main {
  display: grid;
  grid-template-columns: 200px 1fr 1fr;
  grid-template-areas: "h h h" "s c c";
  gap: 16px;
}

@media (max-width: 600px) {
  .sidebar { display: none; }
}
@media (prefers-color-scheme: dark) { ... }
@media (prefers-reduced-motion: reduce) { ... }

/* flex */ display: flex; place-content: center;
/* grid */ display: grid; place-items: center;
/* block */ margin-inline: auto; width: fit-content;

overflow: hidden | auto | scroll;
text-overflow: ellipsis;
white-space: nowrap;
scroll-behavior: smooth;

:root {
  --brand: #6c5ce7;
  --gap: 12px;
}
.btn {
  background: var(--brand);
  padding: var(--gap, 8px);
}

button {
  transition: transform .2s ease, background .2s;
}
button:hover { transform: scale(1.05); }

@keyframes pulse {
  from { opacity: 1; }
  50%  { opacity: .4; }
  to   { opacity: 1; }
}
.dot { animation: pulse 1.5s infinite; }

@container (min-width: 400px) {
  .card { display: flex; }
}
.wrap { container-type: inline-size; }

.card:has(img) { padding: 0; }
:is(h1, h2, h3) { margin-block: 1em; }
:where(.a, .b) p { color: gray; }

.card {
  padding: 1rem;
  & h2 { margin: 0; }
  &:hover { background: #eee; }
}

margin-inline: auto;
padding-block: 1rem;
border-inline-start: 1px solid;

img {
  aspect-ratio: 16 / 9;
  object-fit: cover;
  width: 100%;
}

html { scroll-snap-type: y mandatory; }
section { scroll-snap-align: start; }
th { position: sticky; top: 0; }

filter: blur(4px) brightness(1.2);
backdrop-filter: blur(8px);
mix-blend-mode: multiply;

background: linear-gradient(135deg, #6c5ce7, #00cec9);
background: radial-gradient(circle at 30% 20%, #fff3, transparent 60%);
background: conic-gradient(from 0deg, red, blue);

@property --a {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.ring { background: conic-gradient(from var(--a), red, blue); animation: spin 4s linear infinite; }

/* avoid deep selectors and !important */
/* contain: layout paint; */
/* content-visibility: auto; */

position: relative;
z-index: 1;
/* new stacking context: opacity < 1, transform, filter, isolation: isolate */
